void Store::rename(const QString& id,QString name){need(!failed_,"library-reopen-after-error");name=name.trimmed();need(!name.isEmpty()&&name.size()<=180&&!name.contains(QChar(0)),"library-title");find(docs_,id).title=name;save();}
void Store::organize(const QString& id,QString folder){need(!failed_,"library-reopen-after-error");need(folder.size()<=180&&!folder.contains(QChar(0)),"library-folder");find(docs_,id).folder=folder;save();}
void Store::trash(const QString& id,bool value){need(!failed_,"library-reopen-after-error");find(docs_,id).trashed=value;save();}
